local module = {}

-- 如果是Module ,并不是特殊字符结尾,则返回true
--- *.d.lua
--- *.services.lua
module.isModuleNotSpecial = function(ins: Instance)
	if not ins:IsA("ModuleScript") then
		return
	end

	local name = ins.Name
	if string.match(name, "%.d$") ~= nil then
		return false
	end
	if string.match(name, "%.services$") ~= nil then
		return false
	end

	return true
end

return module
